   match('ما أبقته هند وما حذفته', [('نتكلّم ولا نُتكلَّم عنّا', 'يبقى: يقول الخطبة في أربع كلمات'), ('أقسم بالليالي', 'يُحذف: لا أحد يشكّ'), ('حرف الضاد كالحجر', 'يبقى: يشعر به كلّ أجنبيّ'), ('ما المعلّم إلّا شمعة', 'يُحذف: صورة ميّتة')]),
   order('رتّب القاعدة', ['ماذا', 'يفعل', 'هذا', 'الأسلوب', 'هنا؟']),
   order('رتّب الطباق', ['نتكلّم', 'ولا', 'نُتكلَّم', 'عنّا.']),
   order('رتّب القصر الذي بقي', ['ما', 'جئنا', 'إلى', 'المعهد', 'إلّا', 'طلّابًا.']),
