   cloze('أكمل ما قاله كين', 'أحصى كين ___ صور في ثلاث دقائق، وفهم ___ حرفيًّا، وظنّ أنّ المعهد سيعطيهم ___.', ['تسع', 'المفتاح', 'مفاتيح'], ['ثلاث', 'الحجر', 'كتبًا']),
